// ============================================================
// THE MYTH MUSEUM — documented failed, debunked, and overclaimed
// therapies, each with: the claim, the verdict, WHY it failed
// (with a named, checkable source anchor), an honest analysis of
// its cultural appeal (labeled analysis, not fact), and where
// applicable a real, mapped alternative. Entries never contradict
// protocols in our own cited library. Source anchors are named
// works/rulings as documented in the skeptical and clinical
// literature; the standing citation audit covers this page family
// too (/corrections).
// ============================================================

export type MythVerdict = "DEBUNKED" | "NO EVIDENCE" | "HARMFUL" | "REPLICATION FAILED" | "OVERCLAIMED";

export type Myth = {
  id: string;
  name: string;
  claim: string;    // what it promised, one sentence
  verdict: MythVerdict;
  why: string;      // why it failed, sourced
  source: string;   // named checkable anchor (author/year/venue/ruling)
  appeal: string;   // the cultural-appeal analysis — labeled as analysis
  instead?: string; // a real library protocol or line to point to
};

export const MYTH_VERDICT_META: Record<MythVerdict, { color: string; note: string }> = {
  DEBUNKED: { color: "#E2604A", note: "tested properly, failed decisively" },
  "NO EVIDENCE": { color: "#D08B6C", note: "never produced controlled evidence for its claims" },
  HARMFUL: { color: "#EE6A4F", note: "documented harm — worse than doing nothing" },
  "REPLICATION FAILED": { color: "#E0C68C", note: "a famous finding that would not replicate" },
  OVERCLAIMED: { color: "#CBAA6A", note: "a real kernel, sold far beyond its evidence" },
};

